-- Propiedad de SPEC-102 §4 y SPEC-005 §4.4. ARCHIVO GENERADO: no se edita a mano.
-- Lo produce scripts/mapa/generar_semilla_mapa.py desde docs/dominio/datos/.
-- Para cambiar un dato, se corrige la fuente y se vuelve a generar.
--
-- Contornos y alturas de edificios: (c) colaboradores de OpenStreetMap (ODbL).

-- ======================================================================
-- Sectores
-- ======================================================================

-- ======================================================================
-- Secciones: areas verdes y xerofiticas
-- ======================================================================

-- ======================================================================
-- Contorno y area de cada sector
-- ======================================================================
UPDATE zones s SET boundary = u.geom, area_m2 = u.area FROM (
    SELECT parent_zone_id AS id, ST_Multi(ST_Union(boundary)) AS geom, SUM(area_m2) AS area
      FROM zones
     WHERE parent_zone_id IS NOT NULL AND zone_type_item_id = (SELECT ci.id FROM catalog_items ci JOIN catalog_types ct ON ct.id = ci.catalog_type_id WHERE ct.code = 'ZONE_TYPE' AND ci.code = 'SECTION')
     GROUP BY parent_zone_id
) u WHERE s.id = u.id;

-- ======================================================================
-- Jardines de reserva
-- ======================================================================
CREATE TEMP TABLE reserve_gardens (code TEXT, name TEXT, owner TEXT, geom GEOMETRY(MultiPolygon, 4326));

-- ======================================================================
-- Reserva aplicada a secciones y subsecciones
-- ======================================================================
CREATE TEMP TABLE reserve_in_section AS
SELECT r.*, s.id AS section_id, COUNT(*) OVER (PARTITION BY s.id) AS gardens_in_section
  FROM reserve_gardens r
  JOIN zones s ON ST_Within(ST_PointOnSurface(r.geom), s.boundary)
 WHERE s.zone_type_item_id = (SELECT ci.id FROM catalog_items ci JOIN catalog_types ct ON ct.id = ci.catalog_type_id WHERE ct.code = 'ZONE_TYPE' AND ci.code = 'SECTION');

UPDATE zones z SET is_reservable = TRUE, reservation_owner_item_id = (SELECT ci.id FROM catalog_items ci JOIN catalog_types ct ON ct.id = ci.catalog_type_id WHERE ct.code = 'RESERVATION_OWNER' AND ci.code = r.owner)
  FROM reserve_in_section r WHERE z.id = r.section_id AND r.gardens_in_section = 1;

                   is_reservable, reservation_owner_item_id)
SELECT s.code || '-' || ROW_NUMBER() OVER (PARTITION BY s.id ORDER BY r.code), r.name, s.id,
       (SELECT ci.id FROM catalog_items ci JOIN catalog_types ct ON ct.id = ci.catalog_type_id WHERE ct.code = 'ZONE_TYPE' AND ci.code = 'SUBSECTION'), r.geom, ROUND(ST_Area(r.geom::geography)::numeric, 2),
       TRUE, (SELECT ci.id FROM catalog_items ci JOIN catalog_types ct ON ct.id = ci.catalog_type_id WHERE ct.code = 'RESERVATION_OWNER' AND ci.code = r.owner)
  FROM reserve_in_section r JOIN zones s ON s.id = r.section_id
 WHERE r.gardens_in_section > 1;

-- ======================================================================
-- Zonas de supervision
-- ======================================================================
WITH supervisor AS (
    SELECT u.id FROM users u JOIN catalog_items r ON r.id = u.role_item_id
     WHERE u.is_active AND u.deleted_at IS NULL AND r.code IN ('COORDINADOR', 'ADMIN')
     ORDER BY (r.code = 'COORDINADOR') DESC, u.id LIMIT 1
)
